<?php
declare(strict_types=1);
session_start();
date_default_timezone_set('Africa/Lusaka');
require_once __DIR__ . '/../includes/conn.php';
require_once __DIR__ . '/../includes/auth.php';
require_admin();
$pharmacy_id=(int)($_SESSION['pharmacy_id']??0);
if($pharmacy_id<=0){header('Location: ../index.php?error=session_expired');exit;}
function sr_e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sr_bind(mysqli_stmt $s,string $types,array &$params):void{if($types==='')return;$r=[$types];foreach($params as &$v)$r[]=&$v;call_user_func_array([$s,'bind_param'],$r);}
function sr_rows(mysqli $c,string $sql,string $types,array $params):array{$s=$c->prepare($sql);if(!$s)throw new RuntimeException($c->error);if($types!==''){$p=$params;sr_bind($s,$types,$p);}if(!$s->execute())throw new RuntimeException($s->error);$r=$s->get_result();$out=$r?$r->fetch_all(MYSQLI_ASSOC):[];$s->close();return $out;}
$ph=sr_rows($conn,'SELECT name FROM pharmacies WHERE id=? LIMIT 1','i',[$pharmacy_id]);
$pharmacy_name=$ph[0]['name']??'PHARMACY POS';
$branches=sr_rows($conn,'SELECT id,branch_name FROM branches WHERE pharmacy_id=? AND is_active=1 ORDER BY branch_name','i',[$pharmacy_id]);
$categories=sr_rows($conn,"SELECT DISTINCT category AS name FROM store_items WHERE pharmacy_id=? AND category IS NOT NULL AND TRIM(category)<>'' ORDER BY category",'i',[$pharmacy_id]);
$today=date('Y-m-d');
$period=$_GET['period']??'all';
if(!in_array($period,['all','today','month','custom'],true))$period='all';
$start=trim((string)($_GET['start_date']??''));$end=trim((string)($_GET['end_date']??''));
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start))$start='';
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end))$end='';
if($period==='today'){$start=$today;$end=$today;}
elseif($period==='month'){$start=date('Y-m-01');$end=$today;}
elseif($period==='custom'){if($start==='')$start=date('Y-m-01');if($end==='')$end=$today;if($start>$end)[$start,$end]=[$end,$start];}
else{$start='';$end='';}
$branch_id=(int)($_GET['branch_id']??0);$category=trim((string)($_GET['category']??''));$search=trim((string)($_GET['search']??''));
if($branch_id>0&&!sr_rows($conn,'SELECT id FROM branches WHERE id=? AND pharmacy_id=? AND is_active=1 LIMIT 1','ii',[$branch_id,$pharmacy_id]))$branch_id=0;
$where='s.pharmacy_id=?';$types='i';$params=[$pharmacy_id];
if($period!=='all'){$where.=' AND DATE(COALESCE(s.sale_date,s.created_at)) BETWEEN ? AND ?';$types.='ss';$params[]=$start;$params[]=$end;}
if($branch_id>0){$where.=' AND s.branch_id=?';$types.='i';$params[]=$branch_id;}
if($category!==''){$where.=" AND EXISTS (SELECT 1 FROM sales_items fsi INNER JOIN store_items fi ON fi.id=fsi.product_id AND fi.pharmacy_id=fsi.pharmacy_id WHERE fsi.sale_id=s.id AND fsi.pharmacy_id=s.pharmacy_id AND fsi.branch_id=s.branch_id AND fi.category=?)";$types.='s';$params[]=$category;}
if($search!==''){$where.=" AND (s.invoice LIKE CONCAT('%',?,'%') OR s.issued_by LIKE CONCAT('%',?,'%') OR EXISTS (SELECT 1 FROM users su WHERE su.id=s.user_id AND su.pharmacy_id=s.pharmacy_id AND (su.username LIKE CONCAT('%',?,'%') OR su.full_name LIKE CONCAT('%',?,'%'))) OR EXISTS (SELECT 1 FROM sales_items ssi INNER JOIN store_items si2 ON si2.id=ssi.product_id AND si2.pharmacy_id=ssi.pharmacy_id WHERE ssi.sale_id=s.id AND ssi.pharmacy_id=s.pharmacy_id AND (si2.item_name LIKE CONCAT('%',?,'%') OR si2.barcode LIKE CONCAT('%',?,'%'))))";$types.='ssssss';for($i=0;$i<6;$i++)$params[]=$search;}
$amountExpr="COALESCE(NULLIF(s.total_amount,0),NULLIF(s.total,0),COALESCE(s.subtotal,0)+COALESCE(s.vat_amount,0),0)";
$summary=sr_rows($conn,"SELECT COALESCE(SUM($amountExpr),0) revenue,COUNT(*) invoices FROM sales s WHERE $where",$types,$params)[0]??['revenue'=>0,'invoices'=>0];
$units=sr_rows($conn,"SELECT COALESCE(SUM(si.quantity),0) units FROM sales s INNER JOIN sales_items si ON si.sale_id=s.id AND si.pharmacy_id=s.pharmacy_id AND si.branch_id=s.branch_id WHERE $where",$types,$params)[0]['units']??0;
$daily=sr_rows($conn,"SELECT DATE(COALESCE(s.sale_date,s.created_at)) sale_day,COALESCE(SUM($amountExpr),0) revenue,COUNT(*) invoices FROM sales s WHERE $where GROUP BY DATE(COALESCE(s.sale_date,s.created_at)) ORDER BY sale_day",$types,$params);
$bycat=sr_rows($conn,"SELECT COALESCE(NULLIF(TRIM(i.category),''),'Uncategorised') category,COALESCE(SUM(si.quantity*COALESCE(si.unit_price,i.price)),0) revenue,COALESCE(SUM(si.quantity),0) units FROM sales s INNER JOIN sales_items si ON si.sale_id=s.id AND si.pharmacy_id=s.pharmacy_id AND si.branch_id=s.branch_id INNER JOIN store_items i ON i.id=si.product_id AND i.pharmacy_id=si.pharmacy_id WHERE $where GROUP BY COALESCE(NULLIF(TRIM(i.category),''),'Uncategorised') ORDER BY revenue DESC",$types,$params);
$rows=sr_rows($conn,"SELECT s.id,s.invoice,COALESCE(s.sale_date,s.created_at) sale_datetime,$amountExpr total_amount,s.payment_method,s.payment,b.branch_name,COALESCE(NULLIF(TRIM(u.full_name),''),u.username,s.issued_by,'Unknown') cashier,COALESCE((SELECT SUM(si2.quantity) FROM sales_items si2 WHERE si2.sale_id=s.id AND si2.pharmacy_id=s.pharmacy_id AND si2.branch_id=s.branch_id),0) units,COALESCE((SELECT COUNT(*) FROM sales_items si3 WHERE si3.sale_id=s.id AND si3.pharmacy_id=s.pharmacy_id AND si3.branch_id=s.branch_id),0) item_lines FROM sales s LEFT JOIN branches b ON b.id=s.branch_id AND b.pharmacy_id=s.pharmacy_id LEFT JOIN users u ON u.id=s.user_id AND u.pharmacy_id=s.pharmacy_id WHERE $where ORDER BY COALESCE(s.sale_date,s.created_at) DESC,s.id DESC",$types,$params);
$branch_label='All branches';foreach($branches as $b)if((int)$b['id']===$branch_id)$branch_label=$b['branch_name'];
$period_label=$period==='all'?'All time':($period==='today'?'Today':($period==='month'?'This month':date('d M Y',strtotime($start)).' â€“ '.date('d M Y',strtotime($end))));
$user_role=current_role();$user_display_name=current_user();$branch_count=count($branches);$total_orders=(int)$summary['invoices'];$current_admin_page='sales_report.php';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sales Report | <?=sr_e($pharmacy_name)?></title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>
:root{--blue:#246bfe;--bg:#f4f6f8;--border:#dfe4e9;--text:#1d252d;--muted:#718091;--green:#159a68;--orange:#e7a72e;--red:#d94d61}*{box-sizing:border-box}html,body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,Arial,sans-serif}.admin-main{margin-left:250px;min-height:100vh}.content{padding:22px 28px 35px}.head{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:18px}.head h1{font-size:29px;margin:0;font-weight:850}.head p{margin:6px 0 0;color:var(--muted);font-size:13px}.btn{height:40px;padding:0 14px;border:1px solid var(--border);border-radius:8px;background:#fff;font-weight:800;cursor:pointer}.primary{background:var(--blue);border-color:var(--blue);color:#fff}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:16px}.card{background:#fff;border:1px solid var(--border);border-radius:12px;box-shadow:0 4px 18px rgba(31,40,49,.06)}.kpi{padding:17px 18px;min-height:104px;border-top:3px solid var(--blue)}.kpi:nth-child(2){border-top-color:var(--green)}.kpi:nth-child(3){border-top-color:var(--orange)}.kpi:nth-child(4){border-top-color:#7658e8}.label{font-size:10px;text-transform:uppercase;font-weight:800;letter-spacing:.7px;color:#687587}.value{font-size:27px;font-weight:850;margin-top:8px}.filters{padding:16px;margin-bottom:16px}.grid{display:grid;grid-template-columns:1.3fr 1fr 1fr 1fr 1fr auto;gap:10px}.field label{display:block;font-size:9px;text-transform:uppercase;font-weight:800;color:#687587;margin-bottom:6px}.field input,.field select{width:100%;height:40px;border:1px solid #d8dee5;border-radius:7px;background:#fff;padding:0 10px}.period-row{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-top:10px}.charts{display:grid;grid-template-columns:1.4fr 1fr;gap:16px;margin-bottom:16px}.chart-card{padding:18px}.chart-title{font-weight:850;font-size:14px;margin-bottom:14px}.bars{height:190px;display:flex;align-items:flex-end;gap:8px;overflow-x:auto;border-bottom:1px solid #e6eaf0;padding:10px 4px}.bar-wrap{min-width:34px;height:170px;display:flex;align-items:flex-end;justify-content:center;position:relative}.bar{width:24px;background:#246bfe;border-radius:5px 5px 0 0;min-height:2px}.bar-label{position:absolute;bottom:-24px;font-size:8px;color:#7d8997;white-space:nowrap;transform:rotate(-35deg);transform-origin:top left}.bar-value{position:absolute;top:0;font-size:8px;color:#506071;white-space:nowrap}.cat-list{display:flex;flex-direction:column;gap:9px}.cat-line{display:grid;grid-template-columns:1fr auto;gap:10px;font-size:11px}.cat-line b{font-size:11px}.cat-track{height:7px;background:#edf1f5;border-radius:10px;overflow:hidden;grid-column:1/-1}.cat-track span{display:block;height:100%;background:#159a68;border-radius:10px}.table-card{overflow:hidden}.table-head{padding:16px 18px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;font-weight:850}.muted{color:#8793a0}.wrap{overflow:auto}.table{width:100%;min-width:1000px;border-collapse:collapse}.table th{padding:12px 14px;background:#f6f8fa;color:#647184;font-size:10px;text-transform:uppercase;text-align:left;letter-spacing:.5px}.table td{padding:13px 14px;border-top:1px solid #edf0f3;font-size:12px}.badge{display:inline-block;background:#edf3ff;color:#246bfe;border-radius:14px;padding:4px 8px;font-size:10px;font-weight:800}.money{font-weight:850}.empty{text-align:center;padding:55px;color:#8b96a4}@media(max-width:1100px){.kpis{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr 1fr 1fr}.charts{grid-template-columns:1fr}}@media(max-width:768px){.admin-main{margin-left:0}.content{padding:18px 15px}.grid,.period-row,.kpis{grid-template-columns:1fr}.head{align-items:flex-start;flex-direction:column}.head h1{font-size:24px}}@media print{.admin-aside,.admin-header,.filters,.no-print{display:none!important}.admin-main{margin:0}.content{padding:0}.card{box-shadow:none}.charts{page-break-inside:avoid}}
</style></head><body>
<?php require __DIR__.'/actions/admin_aside.php'; ?><div class="admin-main"><?php require __DIR__.'/actions/admin_header.php'; ?><main class="content">
<div class="head"><div><h1><i class="fa-solid fa-chart-line" style="color:#246bfe"></i> Sales Report</h1><p><?=sr_e($pharmacy_name)?> â€” <?=sr_e($branch_label)?> â€” <b><?=sr_e($period_label)?></b></p></div><button class="btn no-print" onclick="window.print()"><i class="fa-solid fa-print"></i> Print / Export</button></div>
<div class="kpis"><div class="card kpi"><div class="label">Total Revenue</div><div class="value">K<?=number_format((float)$summary['revenue'],2)?></div></div><div class="card kpi"><div class="label">Units Sold</div><div class="value"><?=number_format((int)$units)?></div></div><div class="card kpi"><div class="label">Invoices</div><div class="value"><?=number_format((int)$summary['invoices'])?></div></div><div class="card kpi"><div class="label">Report Rows</div><div class="value"><?=number_format(count($rows))?></div></div></div>
<form class="card filters no-print" method="get"><div class="grid"><div class="field"><label>Search</label><input name="search" value="<?=sr_e($search)?>" placeholder="Invoice, product or staff"></div><div class="field"><label>Period</label><select name="period"><option value="all" <?=$period==='all'?'selected':''?>>All time</option><option value="today" <?=$period==='today'?'selected':''?>>Today</option><option value="month" <?=$period==='month'?'selected':''?>>This month</option><option value="custom" <?=$period==='custom'?'selected':''?>>Custom dates</option></select></div><div class="field"><label>Branch</label><select name="branch_id"><option value="0">All branches</option><?php foreach($branches as $b):?><option value="<?=$b['id']?>" <?=$branch_id==(int)$b['id']?'selected':''?>><?=sr_e($b['branch_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Category</label><select name="category"><option value="">All categories</option><?php foreach($categories as $c):?><option value="<?=sr_e($c['name'])?>" <?=$category===$c['name']?'selected':''?>><?=sr_e($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Action</label><button class="btn primary" type="submit"><i class="fa-solid fa-filter"></i> Apply</button></div></div><div class="period-row"><div class="field"><label>Start date (custom)</label><input type="date" name="start_date" value="<?=sr_e($start)?>"></div><div class="field"><label>End date (custom)</label><input type="date" name="end_date" value="<?=sr_e($end)?>"></div><div class="field"><label>&nbsp;</label><a class="btn" href="sales_report.php"><i class="fa-solid fa-rotate-left"></i> Reset to All Time</a></div></div></form>
<div class="charts"><div class="card chart-card"><div class="chart-title">Daily Revenue Trend <span class="muted" style="font-weight:500">(<?=sr_e($period_label)?>)</span></div><?php $maxDaily=0;foreach($daily as $d)$maxDaily=max($maxDaily,(float)$d['revenue']);?><div class="bars"><?php if($daily):foreach($daily as $d):$h=$maxDaily>0?max(3,((float)$d['revenue']/$maxDaily)*150):3;?><div class="bar-wrap"><span class="bar-value">K<?=number_format((float)$d['revenue'],0)?></span><div class="bar" style="height:<?=$h?>px"></div><span class="bar-label"><?=date('d M',strtotime($d['sale_day']))?></span></div><?php endforeach;else:?><div class="empty" style="width:100%;padding:50px">No sales for this period.</div><?php endif;?></div></div>
<div class="card chart-card"><div class="chart-title">Revenue by Category</div><?php $maxCat=0;foreach($bycat as $c)$maxCat=max($maxCat,(float)$c['revenue']);?><?php if($bycat):?><div class="cat-list"><?php foreach($bycat as $c):?><div class="cat-line"><span><?=sr_e($c['category'])?></span><b>K<?=number_format((float)$c['revenue'],2)?></b><div class="cat-track"><span style="width:<?=($maxCat>0?((float)$c['revenue']/$maxCat)*100:0)?>%"></span></div></div><?php endforeach;?></div><?php else:?><div class="empty">No category sales found.</div><?php endif;?></div></div>
<div class="card table-card"><div class="table-head"><span>Sales Register</span><span class="muted"><?=count($rows)?> records</span></div><div class="wrap"><table class="table"><thead><tr><th>#</th><th>Invoice</th><th>Date / Time</th><th>Units</th><th>Branch</th><th>Payment</th><th>Handled By</th><th>Total</th><th>Action</th></tr></thead><tbody><?php if($rows):$n=1;foreach($rows as $r):?><tr><td><?=$n++?></td><td><span class="badge"><?=sr_e($r['invoice'])?></span></td><td><?=sr_e(date('d M Y H:i',strtotime($r['sale_datetime'])))?></td><td><?=number_format((int)$r['units'])?> <span class="muted">(<?=number_format((int)$r['item_lines'])?> lines)</span></td><td><?=sr_e($r['branch_name']??'â€”')?></td><td><?=sr_e($r['payment_method']?:$r['payment']?:'Cash')?></td><td><?=sr_e($r['cashier'])?></td><td class="money">K<?=number_format((float)$r['total_amount'],2)?></td><td><a class="btn" href="view_invoice.php?id=<?=$r['id']?>"><i class="fa-solid fa-eye"></i></a></td></tr><?php endforeach;else:?><tr><td colspan="9" class="empty">No sales found for these criteria.</td></tr><?php endif;?></tbody></table></div></div>
</main></div></body></html>
